ill-color-light)}.review-target span{color:var(--el-text-color-secondary);font-size:13px}.daily-panel :deep(th.el-table__cell){background:var(--el-fill-color-light);font-weight:700}:global(.inventory-export-date-popper){border:1px solid #cfdef1!important;border-radius:12px!important;box-shadow:0 12px 32px rgb(32 80 132 / 16%)!important;overflow:hidden}:global(.inventory-export-date-popper .el-picker-panel__body-wrapper){background:#fff}:global(.inventory-export-date-popper .el-picker-panel__icon-btn),:global(.inventory-export-date-popper .el-date-picker__header-label),:global(.inventory-export-date-popper .el-date-range-picker__header){color:#315b8b}:global(.inventory-export-date-popper td.available:hover),:global(.inventory-export-date-popper td.today .el-date-table-cell__text){color:#2f74c0}:global(.inventory-export-date-popper td.in-range .el-date-table-cell){background:#edf5ff}:global(.inventory-export-date-popper td.start-date .el-date-table-cell),:global(.inventory-export-date-popper td.end-date .el-date-table-cell){background:#3d82cd}:global(.inventory-export-date-popper td.start-date .el-date-table-cell__text),:global(.inventory-export-date-popper td.end-date .el-date-table-cell__text){color:#fff}@media(max-width:960px){.daily-header{flex-direction:column}.daily-toolbar{justify-content:flex-start}.export-date-filter{width:100%;box-sizing:border-box}.export-date-filter :deep(.el-date-editor),.daily-toolbar :deep(.el-select),.daily-toolbar :deep(.el-input){width:100%}.export-date-filter__label{min-width:64px}.daily-stats{grid-template-columns:repeat(2,minmax(110px,1fr))}.section-heading{align-items:flex-start;flex-direction:column;gap:3px}}
</style>
